def logo(nombre, x, y, alto, color=None):
    """Un logo como <svg> anidado, a la altura pedida y en su color de marca."""
    if nombre == "vapi":
        vb, d, c = VAPI[0], VAPI[1], "#000000"
    elif nombre == "twilio":
        vb, d, c = TWILIO
    else:
        vb, d, c = SIMPLE[nombre]
    w_vb, h_vb = (float(v) for v in vb.split()[2:])
    ancho = alto * w_vb / h_vb
    return (f'<svg x="{x:.1f}" y="{y:.1f}" width="{ancho:.1f}" height="{alto:.1f}" viewBox="{vb}">'
            f'<path d="{d}" fill="{color or c}"/></svg>')


def ancho_logo(nombre, alto):
    vb = VAPI[0] if nombre == "vapi" else TWILIO[0] if nombre == "twilio" else SIMPLE[nombre][0]
    w_vb, h_vb = (float(v) for v in vb.split()[2:])
    return alto * w_vb / h_vb
